function evenNumbersFromTiles(tiles: number[]): number[] {
  const found = new Set<number>();
  const n = tiles.length;
  for (let i = 0; i < n; i++) {
    if (tiles[i] === 0) continue;
    for (let j = 0; j < n; j++) {
      if (j === i) continue;
      for (let k = 0; k < n; k++) {
        if (k === i || k === j || tiles[k] % 2 !== 0) continue;
        found.add(tiles[i] * 100 + tiles[j] * 10 + tiles[k]);
      }
    }
  }
  return [...found].sort((a, b) => a - b);
}

