function evenNumbersFromTiles(tiles: number[]): number[] {
  const have = new Array(10).fill(0);
  for (const d of tiles) have[d]++;
  const out: number[] = [];
  for (let x = 100; x < 1000; x += 2) {
    const need = new Array(10).fill(0);
    need[Math.floor(x / 100)]++;
    need[Math.floor(x / 10) % 10]++;
    need[x % 10]++;
    if (need.every((c, d) => c <= have[d])) out.push(x);
  }
  return out;
}

